#include "PluginProcessor.h"
using namespace juce;
int main(int, char** v) { ScopedJuceInitialiser_GUI g; int nanTotal = 0; AudioFormatManager fm; fm.registerBasicFormats(); std::unique_ptr<AudioFormatReader> rd(fm.createReaderFor(File(v[1]))); AudioBuffer<float> voice(2, 240000); rd->read(&voice, 0, 240000, 0, true, true); { int nf = 0; for (int i = 0; i < 240000; ++i) if (!std::isfinite(voice.getSample(0, i))) ++nf; printf("voice nonfinite %d max %f\n", nf, voice.getMagnitude(0, 240000)); }
 for (int rep = 0; rep < 60; ++rep) { SpeakitProcessor p; for (auto* q : p.getParameters()) if (auto* w = dynamic_cast<RangedAudioParameter*>(q)) w->setValueNotifyingHost(w->getDefaultValue()); for (auto& b : p.bay) for (auto& s : b) s.on = false; auto S = [&](const char* i, float x) { auto* q = p.apvts.getParameter(i); q->setValueNotifyingHost(q->convertTo0to1(x)); }; S("spkOn", 0); S("codec", 0); S("roomOn", 1); S("room", 1); S("roomIdx", (float)(rep % 15)); p.setRateAndBufferSizeDetails(48000, 512); p.prepareToPlay(48000, 512); p.service(); Thread::sleep(rep % 3 == 0 ? 0 : rep % 3 == 1 ? 40 : 350);
  AudioBuffer<float> b(voice); MidiBuffer m; int first = -1; float mx = 0; for (int s = 0; s < 240000; s += 512) { int n = jmin(512, 240000 - s); float* ch[2] = { b.getWritePointer(0, s), b.getWritePointer(1, s) }; AudioBuffer<float> c(ch, 2, n); p.processBlock(c, m); for (int i = 0; i < n; ++i) { float y = ch[0][i]; if (!std::isfinite(y)) { if (first < 0) first = s + i; } else mx = jmax(mx, std::abs(y)); } } if (first >= 0) printf("BAD rep %d room %d first bad %d max %f\n", rep, rep % 15, first, mx); if (first >= 0) ++nanTotal; } printf("bad runs %d\n", nanTotal); return 0; }
